                    "translation": "她会通过很多小细节表现快乐。她在菜园干活时会微笑，有时还会哼一首老歌；新蔬菜开始生长时，她会很兴奋。亲戚来看她时，她会把新鲜蔬菜分给大家，也很喜欢看到一家人坐在一起吃饭。"
