              "translation": "如果有人半天没回我，我尽量不妄下结论，因为通常都有说得过去的原因，所以我会先往好处想。要是真的很急，我就委婉地再提醒一次。工作上我反过来做：让所有人随时知道进展，不让谁等上好几个小时。"
